python3 - << 'PYEOF'
import json

AGENT_PROJECT_ID = "dd643c3f-e8a9-4396-bd4d-0177ecf39fce"
FLOW_FILE = "/work/output/artifacts/skill-flow-devcon-billing-resolution-writer/BillingResolutionWriter/BillingResolutionWriter/BillingResolutionWriter.flow"

flow = json.load(open(FLOW_FILE))
agent_def = json.load(open('/tmp/agent_def_clean.json'))
end_def = json.load(open('/tmp/end_def_clean.json'))
trigger_def = json.load(open('/tmp/def_trigger.json'))['Data']['Node']

# Add outputs to start trigger node
flow['nodes'][0]['outputs'] = {
    "output": {
        "type": "object",
        "description": "Data passed when manually triggering the process.",
        "source": "null",
        "var": "output"
    }
}

# Add agent node
agent_node = {
    "id": "draftEmail",
    "type": "uipath.agent.autonomous",
    "typeVersion": "1.3",
    "display": {"label": "Draft Billing Resolution Email"},
    "inputs": {
        "systemPrompt": "You are a billing resolution specialist.",
        "userPrompt": "Draft a billing resolution email.",
        "source": AGENT_PROJECT_ID,
        "agentInputVariables": [
            {"id": "start__output__customerName",  "type": "string", "binding": "=$vars.start.output.customerName",  "description": "Bound from $vars.start.output.customerName"},
            {"id": "start__output__invoiceNumber", "type": "string", "binding": "=$vars.start.output.invoiceNumber", "description": "Bound from $vars.start.output.invoiceNumber"},
            {"id": "start__output__creditAmount",  "type": "number", "binding": "=$vars.start.output.creditAmount",  "description": "Bound from $vars.start.output.creditAmount"}
        ],
        "agentOutputVariables": [
            {"id": "subject", "type": "string"},
            {"id": "body",    "type": "string"}
        ]
    },
    "outputs": {
        "error": {
            "type": "object",
            "description": "Error information if the node fails",
            "source": "=Error",
            "var": "error"
        }
    }
}

# Add end node
end_node = {
    "id": "endNode",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": {"label": "End"},
    "inputs": {},
    "outputs": {
        "emailSubject": {
            "type": "string",
            "source": "=js:$vars.draftEmail.output.subject",
            "var": "emailSubject"
        },
        "emailBody": {
            "type": "string",
            "source": "=js:$vars.draftEmail.output.body",
            "var": "emailBody"
        }
    }
}

flow['nodes'].append(agent_node)
flow['nodes'].append(end_node)

# Edges
flow['edges'] = [
    {"id": "e-start-draftEmail", "sourceNodeId": "start",      "sourcePort": "output",  "targetNodeId": "draftEmail", "targetPort": "input"},
    {"id": "e-draftEmail-end",   "sourceNodeId": "draftEmail", "sourcePort": "success", "targetNodeId": "endNode",    "targetPort": "input"}
]

# Definitions
flow['definitions'] = [trigger_def, agent_def, end_def]

# Variables
flow['variables'] = {
    "globals": [
        {"id": "customerName",  "type": "string", "direction": "in",  "triggerNodeId": "start"},
        {"id": "invoiceNumber", "type": "string", "direction": "in",  "triggerNodeId": "start"},
        {"id": "creditAmount",  "type": "number", "direction": "in",  "triggerNodeId": "start"},
        {"id": "emailSubject",  "type": "string", "direction": "out"},
        {"id": "emailBody",     "type": "string", "direction": "out"}
    ],
    "nodes": [
        {"id": "start.output",       "type": "object", "binding": {"nodeId": "start",      "outputId": "output"}},
        {"id": "draftEmail.output",  "type": "object", "binding": {"nodeId": "draftEmail", "outputId": "output"}},
        {"id": "draftEmail.error",   "type": "object", "binding": {"nodeId": "draftEmail", "outputId": "error"}}
    ],
    "variableUpdates": []
}

# Layout
flow['layout'] = {
    "nodes": {
        "start":      {"position": {"x": 0, "y": 0},   "size": {"width": 96, "height": 96},  "collapsed": False},
        "draftEmail": {"position": {"x": 0, "y": 0},   "size": {"width": 288, "height": 96}, "collapsed": False},
        "endNode":    {"position": {"x": 0, "y": 0},   "size": {"width": 96, "height": 96},  "collapsed": False}
    }
}

json.dump(flow, open(FLOW_FILE, 'w'), indent=2)
print("Flow written OK")
PYEOF

